// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.Initialized();
    }

    function testFuzz_property(uint256 _val) public {
        uint256 before = c.MinSum();
        bool ok = true;
        try c.SetMinSum(_val) {
            // succeeded (reference should not reach here)
        } catch {
            ok = false;
        }

        // General rule: after Initialized(), SetMinSum must ALWAYS revert and MinSum must not change.
        assertTrue(!ok && c.MinSum() == before);
    }
}
